<?php
declare(strict_types=1); require_once __DIR__.'/../auth/role_helper.php'; $allowedRoles=[ROLE_DISCIPLINARY_OFFICER]; require_once __DIR__.'/../auth/session_guard.php';
$pageTitle='Follow-ups';$activePage='guidance_followups';$roleStylesheet='assets/css/teacher.css';$pageStylesheet='assets/css/pages/guidance.css';$userId=(int)$_SESSION['user_id'];
$view=($_GET['view']??'calendar')==='list'?'list':'calendar';$requestedMonth=trim((string)($_GET['month']??''));$month=preg_match('/^\d{4}-(?:0[1-9]|1[0-2])$/',$requestedMonth)===1?$requestedMonth:(new DateTimeImmutable('now'))->format('Y-m');
$stmt=$pdo->prepare("SELECT f.guidance_followup_id,f.guidance_case_id,f.scheduled_at,f.followup_status,gc.case_number,CONCAT_WS(' ',s.first_name,s.last_name) student_name FROM guidance_followups f INNER JOIN guidance_cases gc ON gc.guidance_case_id=f.guidance_case_id INNER JOIN teacher_referrals tr ON tr.teacher_referral_id=gc.teacher_referral_id INNER JOIN students s ON s.student_id=tr.student_id WHERE f.assigned_user_id=? ORDER BY f.scheduled_at ASC");$stmt->execute([$userId]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$monthStart = new DateTimeImmutable($month . '-01');
$monthEnd = $monthStart->modify('last day of this month');
$calendarStart = $monthStart->modify('-' . (int) $monthStart->format('w') . ' days');
$calendarEnd = $monthEnd->modify('+' . (6 - (int) $monthEnd->format('w')) . ' days');
$previousMonth = $monthStart->modify('-1 month')->format('Y-m');
$nextMonth = $monthStart->modify('+1 month')->format('Y-m');
$eventsByDate = [];
foreach($rows as $row){$date=substr((string)$row['scheduled_at'],0,10);$eventsByDate[$date][]=$row;}
$groups=['Overdue'=>[],'Due today'=>[],'Upcoming'=>[],'Completed'=>[],'Cancelled'=>[]];foreach($rows as $row){$time=strtotime((string)$row['scheduled_at']);$overdue=$row['followup_status']==='Scheduled'&&$time<time();if($overdue)$groups['Overdue'][]=$row;elseif($row['followup_status']==='Scheduled'&&date('Y-m-d',$time)===date('Y-m-d'))$groups['Due today'][]=$row;elseif($row['followup_status']==='Scheduled')$groups['Upcoming'][]=$row;elseif($row['followup_status']==='Completed')$groups['Completed'][]=$row;else$groups['Cancelled'][]=$row;}
function guidanceFollowupEsc(?string $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><?php require __DIR__.'/../includes/components/head.php';?><body><?php require __DIR__.'/../includes/components/sidebar.php';?><main class="main-content"><div class="main-wrapper"><?php require __DIR__.'/../includes/components/top-navbar.php';?><section class="guidance-page guidance-worklist-page guidance-followup-calendar-page"><header class="guidance-page-header"><div><p class="page-eyebrow">Disciplinary Officer</p><h1>Follow-ups</h1><p class="guidance-context-meta">Scheduled work · <?=guidanceFollowupEsc($monthStart->format('F Y'))?></p></div><div class="guidance-view-toggle"><a class="btn <?=$view==='calendar'?'btn-primary':'btn-secondary'?>" href="?view=calendar&amp;month=<?=guidanceFollowupEsc($month)?>" aria-current="<?=$view==='calendar'?'page':'false'?>">Calendar</a><a class="btn <?=$view==='list'?'btn-primary':'btn-secondary'?>" href="?view=list&amp;month=<?=guidanceFollowupEsc($month)?>" aria-current="<?=$view==='list'?'page':'false'?>">List</a></div></header>
<?php if($view==='calendar'): ?><div class="guidance-followup-split"><section class="guidance-panel guidance-calendar-panel"><div class="guidance-panel-heading"><a class="guidance-calendar-nav" href="?view=calendar&amp;month=<?=$previousMonth?>" aria-label="Previous month">‹</a><div><p class="guidance-section-kicker">Schedule</p><h2><?=guidanceFollowupEsc($monthStart->format('F Y'))?></h2></div><a class="guidance-calendar-nav" href="?view=calendar&amp;month=<?=$nextMonth?>" aria-label="Next month">›</a></div><p class="guidance-calendar-scroll-hint">Swipe to see all seven days</p><div class="guidance-calendar-scroll" role="region" aria-label="Follow-up calendar. Scroll horizontally to view all seven days." tabindex="0"><div class="guidance-calendar-weekdays"><?php foreach(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as $weekday):?><span><?= $weekday ?></span><?php endforeach;?></div><div class="guidance-calendar-grid"><?php for($day=$calendarStart;$day<=$calendarEnd;$day=$day->modify('+1 day')):$date=$day->format('Y-m-d');$inMonth=$day->format('Y-m')===$month;$dayEvents=$eventsByDate[$date]??[];?><div class="guidance-calendar-day <?=$inMonth?'':'is-outside'?> <?=$date===date('Y-m-d')?'is-today':''?>"><b><?=$day->format('j')?></b><?php foreach(array_slice($dayEvents,0,3) as $event):?><a class="guidance-calendar-event <?=strtolower((string)$event['followup_status'])?>" href="<?=APP_URL?>/dashboard/guidance_case.php?case_id=<?=(int)$event['guidance_case_id']?>" title="<?=guidanceFollowupEsc($event['student_name'])?> · <?=guidanceFollowupEsc($event['followup_status'])?>"><?=guidanceFollowupEsc($event['student_name'])?></a><?php endforeach;if(count($dayEvents)>3):?><small>+<?=count($dayEvents)-3?> more</small><?php endif;?></div><?php endfor;?></div></div></section><aside class="guidance-panel guidance-scheduled-panel"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Worklist</p><h2>Scheduled appointments</h2></div><span class="guidance-count-badge"><?=count($rows)?></span></div><?php if($rows===[]):?><div class="guidance-empty-state is-compact">No follow-ups scheduled.</div><?php else:?><div class="guidance-agenda-list"><?php foreach($rows as $row):$time=strtotime((string)$row['scheduled_at']);$isOverdue=$row['followup_status']==='Scheduled'&&$time<time();?><article class="guidance-agenda-item"><time><?=guidanceFollowupEsc(date('M j',$time))?><b><?=guidanceFollowupEsc(date('g:i A',$time))?></b></time><span><strong><?=guidanceFollowupEsc($row['student_name'])?></strong><small><?=guidanceFollowupEsc($row['case_number'])?></small></span><span class="guidance-status <?=$isOverdue?'overdue':strtolower((string)$row['followup_status'])?>"><?=$isOverdue?'Overdue':guidanceFollowupEsc($row['followup_status'])?></span><a class="btn btn-secondary" href="<?=APP_URL?>/dashboard/guidance_case.php?case_id=<?=(int)$row['guidance_case_id']?>">Open</a></article><?php endforeach;?></div><?php endif;?></aside></div>
<?php else: ?><div class="guidance-agenda-grid guidance-agenda-list-view"><?php foreach($groups as $group=>$items):$anchor='agenda-'.strtolower(str_replace(' ','-',$group));?><section class="guidance-panel guidance-agenda-panel" aria-labelledby="<?=$anchor?>"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Agenda</p><h2 id="<?=$anchor?>"><?=guidanceFollowupEsc($group)?></h2></div><span class="guidance-count-badge"><?=count($items)?></span></div><?php if($items===[]):?><div class="guidance-empty-state is-compact">No <?=strtolower(guidanceFollowupEsc($group))?> follow-ups.</div><?php else:?><div class="guidance-agenda-list"><?php foreach($items as $row):$time=strtotime((string)$row['scheduled_at']);?><article class="guidance-agenda-item"><time><?=guidanceFollowupEsc(date('M j',$time))?><b><?=guidanceFollowupEsc(date('g:i A',$time))?></b></time><span><strong><?=guidanceFollowupEsc($row['student_name'])?></strong><small><?=guidanceFollowupEsc($row['case_number'])?></small></span><span class="guidance-status <?=$group==='Overdue'?'overdue':strtolower((string)$row['followup_status'])?>"><?=$group==='Overdue'?'Overdue':guidanceFollowupEsc($row['followup_status'])?></span><a class="btn btn-secondary" href="<?=APP_URL?>/dashboard/guidance_case.php?case_id=<?=(int)$row['guidance_case_id']?>">Open</a></article><?php endforeach;?></div><?php endif;?></section><?php endforeach;?></div><?php endif;?></section></div></main><?php require __DIR__.'/../includes/components/footer.php';?></body></html>
